const input=$json.body??$json;
const a=input.seller_response_analysis??{};
const classification=String(a.classification||input.classification||"").toLowerCase();
const mao=Number(input.dynamic_mao??input.adjusted_mao??input.mao);
const counter=Number(a.counteroffer_amount??input.counteroffer_amount);
const validMao=Number.isFinite(mao)&&mao>0;
const validCounter=Number.isFinite(counter)&&counter>0;
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const motivation=Number(input.motivation_score??input.motivation??0);
let strategy="human_review",decision="needs_review",nextWorkflow="WF-126",human=true,reason="negotiation strategy requires review";
if(input.dnc||input.do_not_contact){decision="blocked_dnc";reason="seller is do-not-contact";}
else if(blockers.length){decision="blocked";reason="active blockers present";}
else if(!validMao){decision="mao_missing";reason="dynamic MAO is missing or invalid";}
else if(classification==="accepted"){
  decision="acceptance_ready";strategy="prepare_contract";nextWorkflow="WF-293";reason="seller accepted; preserve dynamic MAO and move to contract decision";
}
else if(classification==="counteroffer_or_price_question"&&validCounter){
  if(counter<=mao){decision="counteroffer_within_mao";strategy="accept_or_contract";nextWorkflow="WF-293";reason="counteroffer is within dynamic MAO";}
  else if(counter<=mao*1.10){decision="counteroffer_near_mao";strategy="revised_offer_or_walkaway";nextWorkflow="WF-293";reason="counteroffer is above MAO but within controlled 10% negotiation band";}
  else{decision="counteroffer_above_mao";strategy="walkaway_or_reengage";nextWorkflow="WF-294";reason="counteroffer exceeds protected dynamic MAO";}
}
else if(classification==="rejected"){decision="reengage";strategy="reengagement";nextWorkflow="WF-294";reason="seller rejected the offer";}
else if(classification==="question"){decision="clarify";strategy="clarification";nextWorkflow="WF-294";reason="seller needs clarification before negotiation can continue";}
else if(classification==="no_response"){decision="timeout";strategy="followup";nextWorkflow="WF-290";human=false;reason="seller response timed out";}
else{decision="other_response";strategy="review_and_clarify";nextWorkflow="WF-294";reason="seller response requires contextual negotiation review";}
const guardrail=(validCounter&&counter>mao)?"HARD_BLOCK_ABOVE_DYNAMIC_MAO":"PASS";
const idempotencyKey=input.idempotency_key||`wf-297:${input.deal_id||input.dispatch_id||"unknown"}:${input.provider_event_id||input.version||1}`;
return [{json:{...input,workflow:"WF-297",workflow_name:"AI Seller Response Classification → Negotiation Strategy & Dynamic MAO Controller",status:decision==="blocked_dnc"?"blocked_dnc":decision==="blocked"?"negotiation_blocked":decision==="mao_missing"?"negotiation_review_required":"strategy_ready",negotiation_strategy:{decision,strategy,reason,dynamic_mao:validMao?mao:null,counteroffer_amount:validCounter?counter:null,motivation_score:Number.isFinite(motivation)?motivation:null,guardrail,protected_mao:true},next_workflow:nextWorkflow,human_review_required:human,audit:{event_type:"ai_negotiation_strategy_dynamic_mao",idempotency_key:idempotencyKey}}}];
